    return '<div class="as-sw-tabs' + (cls ? ' ' + cls : '') + '">' + labels.map(function (l, i) { return '<button type="button"' + (i ? '' : ' class="on"') + '>' + T(l) + '<i></i></button>'; }).join('') + '</div>';
